type IsString<T> = T extends string ? true : false;

type A = IsString<'hello'>; // true
type B = IsString<42>;     // false

// React example: extract event handler type
type ExtractEventHandler<T> = T extends (event: infer E) => void
  ? E
  : never;

type ClickEvent = ExtractEventHandler<(e: MouseEvent) => void>; // MouseEvent

interface User {
  id: number;
  name: string;
  email: string;
}

// Make all properties optional
type PartialUser = {
  [K in keyof User]?: User[K];
};

// Make all properties readonly
type ReadonlyUser = {
  readonly [K in keyof User]: User[K];
};

// Add a loading state to every property
type LoadingUser = {
  [K in keyof User]: { value: User[K]; loading: boolean };
};

// Remove a property
type UserWithoutEmail = {
  [K in keyof User as Exclude<K, 'email'>]: User[K];
};
